export function createLedger() {
  const events = []

  function project(newEvents) {
    const balances = foldEvents(events)

    for (const event of newEvents) {
      validateEvent(event)
      const current = balances.get(event.account) ?? 0
      const delta = event.type === 'credit' ? event.amountCents : -event.amountCents
      const next = current + delta
      if (!Number.isSafeInteger(next)) throw new Error('balance exceeds safe integer range')
      if (next < 0) throw new Error('insufficient funds')
      balances.set(event.account, next)
    }
  }

  function appendBatch(newEvents) {
    if (!Array.isArray(newEvents) || newEvents.length === 0) return
    project(newEvents)

    const firstSeq = events.length
    const committed = newEvents.map((event, index) =>
      Object.freeze({ ...event, seq: firstSeq + index }),
    )
    events.push(...committed)
  }

  return {
    append(event) {
      appendBatch([event])
    },
    appendBatch,
    eventCount() {
      return events.length
    },
    fold() {
      return Object.fromEntries(foldEvents(events))
    },
    events() {
      return events.map((event) => ({ ...event }))
    },
  }
}

function validateEvent(event) {
  if (event === null || typeof event !== 'object') throw new Error('event must be an object')
  if (event.type !== 'debit' && event.type !== 'credit') throw new Error('invalid event type')
  if (!Number.isSafeInteger(event.amountCents) || event.amountCents <= 0) {
    throw new Error('amount must be a positive safe integer')
  }
}

function foldEvents(events) {
  const balances = new Map()
  for (const event of events) {
    const current = balances.get(event.account) ?? 0
    const delta = event.type === 'credit' ? event.amountCents : -event.amountCents
    balances.set(event.account, current + delta)
  }
  return balances
}

